import * as React from "react";
import { cx } from "./cx";
import { Dialog } from "./dialog";

export interface CommandItem {
  label: string;
  hint?: React.ReactNode;
  keywords?: string;
  onSelect?: () => void;
}

export interface CommandGroup {
  label?: string;
  items: CommandItem[];
}

export interface CommandProps extends React.HTMLAttributes<HTMLDivElement> {
  groups: CommandGroup[];
  placeholder?: string;
  emptyLabel?: React.ReactNode;
  onDone?: () => void;
}

/** Filter, arrows, enter. */
export function Command({
  groups,
  placeholder = "Type a command or search…",
  emptyLabel = "Nothing found.",
  onDone,
  className,
  ...props
}: CommandProps) {
  const [query, setQuery] = React.useState("");
  const [activeIndex, setActiveIndex] = React.useState(0);

  const q = query.toLowerCase();
  const filtered = groups
    .map((group) => ({
      ...group,
      items: group.items.filter(
        (item) => item.label.toLowerCase().includes(q) || item.keywords?.toLowerCase().includes(q),
      ),
    }))
    .filter((group) => group.items.length > 0);
  const flat = filtered.flatMap((group) => group.items);

  const run = (item: CommandItem) => {
    onDone?.();
    item.onSelect?.();
  };

  let cursor = -1;
  return (
    <div className={cx(className)} {...props}>
      <input
        className="rs-command-input"
        autoFocus
        placeholder={placeholder}
        role="combobox"
        aria-expanded="true"
        aria-label="Command"
        value={query}
        onChange={(e) => {
          setQuery(e.target.value);
          setActiveIndex(0);
        }}
        onKeyDown={(e) => {
          if (e.key === "ArrowDown") {
            e.preventDefault();
            setActiveIndex((i) => Math.min(flat.length - 1, i + 1));
          }
          if (e.key === "ArrowUp") {
            e.preventDefault();
            setActiveIndex((i) => Math.max(0, i - 1));
          }
          if (e.key === "Enter") {
            e.preventDefault();
            const item = flat[activeIndex];
            if (item) run(item);
          }
        }}
      />
      <div className="rs-command-list" role="listbox">
        {flat.length === 0 && <div className="rs-command-empty">{emptyLabel}</div>}
        {filtered.map((group, gi) => (
          <React.Fragment key={gi}>
            {group.label && <div className="rs-command-group">{group.label}</div>}
            {group.items.map((item) => {
              cursor++;
              const index = cursor;
              return (
                <button
                  key={item.label}
                  type="button"
                  role="option"
                  aria-selected={index === activeIndex}
                  className={cx("rs-command-item", index === activeIndex && "rs-command-item-active")}
                  onPointerEnter={() => setActiveIndex(index)}
                  onClick={() => run(item)}
                >
                  <span>{item.label}</span>
                  {item.hint != null && <span className="rs-command-hint">{item.hint}</span>}
                </button>
              );
            })}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

export interface CommandDialogProps extends CommandProps {
  open: boolean;
  onClose?: () => void;
}

/** The palette in a native <dialog>. Wire ⌘K in your app to setOpen(true). */
export function CommandDialog({ open, onClose, className, ...props }: CommandDialogProps) {
  return (
    <Dialog open={open} onClose={onClose} className={cx("rs-command", className)}>
      {open && <Command onDone={onClose} {...props} />}
    </Dialog>
  );
}

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/* ── Command: one input, everything reachable ── */
.rs-command{width:480px;max-width:90vw;padding:0;overflow:hidden}
.rs-command-input{width:100%;border:none;border-bottom:1px solid var(--divider-subtle);background:none;font-family:inherit;font-size:14px;letter-spacing:-.01em;color:var(--text);padding:14px 16px;outline:none}
.rs-command-input::placeholder{color:var(--text-secondary)}
.rs-command-list{max-height:320px;overflow-y:auto;padding:6px}
.rs-command-group{font-size:11px;font-weight:600;letter-spacing:-.01em;color:var(--text-secondary);padding:8px 10px 4px}
.rs-command-item{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;text-align:left;border:none;background:none;font-family:inherit;font-size:13.5px;letter-spacing:-.01em;color:var(--text);padding:8px 10px;border-radius:var(--radius-sm);cursor:pointer}
.rs-command-item-active{background:var(--divider-subtle)}
.rs-command-hint{font-size:11px;color:var(--text-secondary)}
.rs-command-empty{padding:20px;text-align:center;font-size:13px;color:var(--text-secondary)}
